L000050	\title{Vorticity-Crystalline Order Coupling in Supersolids: Excitations and Re-entrant Phases}
L000051	\author{M. Schubert}
L000052	\email{malte.schubert@fysik.lu.se}
L000053	\affiliation{Mathematical Physics and NanoLund, LTH, Lund University, Box 118, 22100 Lund, Sweden}
